mapper.select:
SELECT qa.allocation_id, qa.allocation_name, qa.year, qa.category_id, '' AS category_name, qa.from_division_id, '' AS from_division_name, qa.from_division_level, qa.from_parent_division_id, '' AS from_parent_division_name, qa.to_division_id, '' AS to_division_name, qa.to_farmer_id, '' AS to_farmer_name, qa.allocated_quota, qa.quota_id, '' AS quota_name, qa.total_received_quota, qa.total_allocated_quota, qa.remaining_quota, qa.allocation_status, CASE qa.allocation_status WHEN 0 THEN 'Not Allocated' WHEN 1 THEN 'Partially Allocated' WHEN 2 THEN 'Completed' ELSE 'Unknown' END AS allocation_status_name, qa.operator_id, '' AS operator_name, qa.operator_division_id, '' AS operator_division_name, qa.modifier_id, '' AS modifier_name, '' AS modifier_division_name, qa.operate_time, qa.progress_update_time, qa.create_time, qa.update_time FROM t_quota_allocation qa
AND qa.year = #{year}
AND qa.category_id = #{categoryId}
AND qa.from_division_id = #{fromDivisionId}
AND qa.from_division_level = #{fromDivisionLevel}
AND qa.allocation_status = #{allocationStatus}
AND qa.operator_division_id = #{operatorDivisionId}
ORDER BY qa.operate_time DESC
